module TopModule (
    input c,
    input d,
    output [3:0] mux_in
);
    assign mux_in[0] = c | d;
    assign mux_in[1] = 1'b0;
    assign mux_in[2] = c | ~d;
    assign mux_in[3] = c & d;
endmodule

module TopModule (
    input  clk,
    input  a,
    output q
);

    reg a_reg;
    reg q_reg;

    always @(posedge clk) begin
        a_reg <= a;
        q_reg <= ~a_reg;
    end

    assign q = q_reg;

endmodule

module TopModule (
    input  logic clk,
    input  logic L,
    input  logic q_in,
    input  logic r_in,
    output logic Q
);

    always_ff @(posedge clk) begin
        if (L)
            Q <= r_in;
        else
            Q <= q_in;
    end

endmodule

module TopModule (
    input  logic clk,
    input  logic L,
    input  logic q_in,
    input  logic r_in,
    output logic Q
);

    always_ff @(posedge clk) begin
        if (L)
            Q <= r_in;
        else
            Q <= q_in;
    end

endmodule

module TopModule (
    input  [3:0] x,
    output       f
);
    assign f = (~x[3] & ~x[2] & ~x[1]) |
               (~x[3] & ~x[1] & x[0]) |
               (~x[3] & x[2] & ~x[1]) |
               (x[2] & x[1] & ~x[0]) |
               (x[3] & x[2] & x[1]);
endmodule

module TopModule (
    input clk,
    input reset,
    input in,
    output done
);

    localparam IDLE  = 3'd0,
               START = 3'd1,
               DATA  = 3'd2,
               STOP  = 3'd3,
               DONE  = 3'd4,
               WAIT  = 3'd5;

    reg [2:0] state, next_state;
    reg [3:0] bit_cnt;

    always @(posedge clk) begin
        if (reset) begin
            state   <= IDLE;
            bit_cnt <= 4'd0;
        end else begin
            state <= next_state;

            if (state == IDLE)
                bit_cnt <= 4'd0;
            else if (state == START)
                bit_cnt <= 4'd0;
            else if (state == DATA)
                bit_cnt <= bit_cnt + 4'd1;
        end
    end

    always @(*) begin
        case (state)
            IDLE:  next_state = in ? IDLE : START;
            START: next_state = DATA;
            DATA:  next_state = (bit_cnt == 4'd7) ? STOP : DATA;
            STOP:  next_state = in ? DONE : WAIT;
            DONE:  next_state = in ? IDLE : START;
            WAIT:  next_state = in ? IDLE : WAIT;
            default: next_state = IDLE;
        endcase
    end

    assign done = (state == DONE);

endmodule
